1: // details feature - uses window.TV (see README "Feature files").
2: // OK on a title opens a full-screen details page (where to watch, trailer, watchlist, more like this).
3: (function () {
4:   var TV = window.TV, esc = TV.esc;
5:   var box = TV.el('div'), stack = [], cache = {}, origin = null;
6:   box.id = 'details'; box.hidden = true;
7:   document.body.appendChild(box);
8: 
9:   // ---------- watchlist ----------
10:   var list = TV.store('watchlist') || [];
11:   function inList(it) { return list.some(function (x) { return x.tmdb.id === it.tmdb.id && x.tmdb.type === it.tmdb.type; }); }
12:   function toggle(it) {
13:     var had = inList(it);
14:     list = list.filter(function (x) { return !(x.tmdb.id === it.tmdb.id && x.tmdb.type === it.tmdb.type); });
15:     if (!had) list.unshift({title: it.title, sub: it.sub, meta: it.meta, img: it.img, bg: it.bg, blur: it.blur, src: it.src, svc: it.svc, tmdb: it.tmdb});
16:     TV.store('watchlist', list);
17:     TV.toast(had ? 'Removed from your watchlist' : 'Added to your watchlist');
18:     TV.refresh();
19:     return !had;
20:   }
21:   TV.addRow(function () { return list.length ? {title: 'My watchlist', items: list} : null; });
22: 
23:   // ---------- data ----------
24:   function load(it) {
25:     var k = it.tmdb.type + '/' + it.tmdb.id;
26:     if (!cache[k]) cache[k] = TV.tmdb(k, '&append_to_response=credits,videos,watch/providers,recommendations')
27:       .then(function (d) { return (cache[k] = d); }, function (e) { delete cache[k]; throw e; });
28:     return cache[k];
29:   }
30:   function names(a) { return (a || []).map(function (p) { return p.provider_name; }).filter(function (n, i, all) { return all.indexOf(n) === i; }); }
31: 
32:   // ---------- render ----------
33:   function btn(label, fn) { var b = TV.el('span', 'dbtn f', label); b.onok = fn; return b; }
34:   function render(it, d) { // d = TMDB details (or null while loading)
35:     var bg = d && d.backdrop_path ? TV.IMG + 'w1280' + d.backdrop_path : it.bg, meta = it.meta, cast = '', extra = '';
36:     if (d) {
37:       var len = d.runtime ? Math.floor(d.runtime / 60) + 'h ' + d.runtime % 60 + 'm'
38:         : d.number_of_seasons ? d.number_of_seasons + (d.number_of_seasons > 1 ? ' seasons' : ' season') : '';
39:       meta = [meta, len, (d.genres || []).slice(0, 3).map(function (g) { return g.name; }).join(', ')].filter(Boolean).join('  ·  ');
40:       cast = (d.credits && d.credits.cast || []).slice(0, 6).map(function (c) { return c.name; }).join(', ');
41:     }
42:     box.innerHTML = '<img class="dbg" alt="" decoding="async"' + (bg ? ' src="' + bg + '"' : '') + '><div class="dshade"></div>' +
43:       '<div class="dbody"><div class="dsrc">' + esc(it.src) + '</div><h1>' + esc(it.title) + '</h1><div class="dmeta">' + esc(meta) + '</div>' +
44:       '<p class="dsub">' + esc(d ? d.overview || it.sub : it.sub) + '</p>' + (cast ? '<div class="dcast">Cast: ' + esc(cast) + '</div>' : '') +
45:       '<div class="dbtns"></div><div class="dextra"></div></div>';
46:     var btns = box.querySelector('.dbtns');
47:     if (d) {
48:       var reg = (d['watch/providers'] || {}).results || {}, here = reg[TV.C.REGION] || {}, seen = {};
49:       (here.flatrate || []).concat(here.ads || [], here.free || []).forEach(function (p) {
50:         var svc = TV.svcFor(p.provider_name);
51:         if (svc && !seen[svc.name] && TV.S.services.indexOf(svc.name) >= 0) { seen[svc.name] = 1; btns.appendChild(btn('▶ Watch on ' + esc(svc.name), function () { TV.openItem(Object.assign({}, it, {svc: svc})); })); }
52:       });
53:       if (!btns.children.length) {
54:         btns.appendChild(TV.el('span', 'dnone', 'Not on your services'));
55:         var rb = names((here.rent || []).concat(here.buy || []));
56:         extra = rb.length ? 'Rent or buy: ' + rb.join(', ') : 'No streaming info for ' + TV.C.REGION;
57:       }
58:       var tr = ((d.videos || {}).results || []).filter(function (v) { return v.site === 'YouTube' && v.type === 'Trailer'; })[0];
59:       if (tr) btns.appendChild(btn('Trailer', function () { TV.launch('youtube.leanback.v4', {contentTarget: 'https://www.youtube.com/tv?v=' + tr.key}); }));
60:     }
61:     var wl = btn(inList(it) ? '✓ In watchlist' : '＋ Watchlist', function () { wl.textContent = toggle(it) ? '✓ In watchlist' : '＋ Watchlist'; });
62:     btns.appendChild(wl);
63:     box.querySelector('.dextra').textContent = extra;
64:     var recs = d && ((d.recommendations || {}).results || []).filter(function (m) { return m.backdrop_path; }).slice(0, 20);
65:     if (recs && recs.length) {
66:       var more = TV.el('section', 'dmore', '<h3>More like this</h3>'), strip = TV.el('div', 'strip');
67:       recs.forEach(function (m) { strip.appendChild(TV.card(Object.assign(TV.fromTmdb(m), {src: 'Because you viewed ' + it.title}))); });
68:       more.appendChild(strip); box.appendChild(more);
69:     }
70:   }
71:   function show(it) {
72:     stack.push(it); box.hidden = false;
73:     var k = it.tmdb.type + '/' + it.tmdb.id;
74:     if (cache[k] && !cache[k].then) return render(it, cache[k]);
75:     render(it, null);
76:     load(it).then(function (d) {
77:       if (stack[stack.length - 1] === it && TV.view() === 'details') { render(it, d); TV.rebuild(0, 0); }
78:     }, function () { TV.toast('Could not load details'); });
79:   }
80:   function hide() {
81:     stack.pop();
82:     var prev = stack[stack.length - 1];
83:     var d = prev && cache[prev.tmdb.type + '/' + prev.tmdb.id];
84:     if (prev) render(prev, d && !d.then ? d : null); else { box.hidden = true; box.innerHTML = ''; }
85:   }
86: 
87:   TV.addView('details', {
88:     nav: function () {
89:       var strip = box.querySelector('.strip');
90:       return [[].slice.call(box.querySelectorAll('.dbtns .f')), strip ? [].slice.call(strip.children) : []];
91:     },
92:     show: show,
93:     hide: hide,
94:     onFocus: function (e, pos) {
95:       if (e.parentNode.classList.contains('strip')) e.parentNode.style.transform = 'translateX(' + -Math.max(0, e.offsetLeft - (pos.c ? 40 : 0)) + 'px)';
96:     },
97:     back: function () {
98:       var o = stack.length === 1 && origin;
99:       TV.closeView();
100:       if (!o || TV.view() !== 'home') return;
101:       // Adding/removing the watchlist row can shift home rows: put focus back on the card we came from.
102:       var secs = [].slice.call(document.querySelectorAll('#rows .row'));
103:       for (var i = 0; i < secs.length; i++) if (secs[i].querySelector('h3').textContent === o.row) return TV.rebuild(2 + i, o.col);
104:     }
105:   });
106: 
107:   function openDetails(it) {
108:     if (!it.tmdb || it.at || it.src === 'YouTube') return TV.openItem(it);
109:     if (TV.view() !== 'details') { // remember where we came from on home
110:       var f = document.querySelector('#rows .focus'), row = f && f.closest('.row');
111:       origin = row ? {row: row.querySelector('h3').textContent, col: [].indexOf.call(f.parentNode.children, f)} : null;
112:     }
113:     TV.openView('details', it);
114:   }
115:   TV.itemOk = openDetails;
116: })();
