      var trailerBtn = document.getElementById('details-trailer-btn');
      if (trailerBtn && !trailerBtn._hasBoundDetailsTrailer) {
        trailerBtn._hasBoundDetailsTrailer = true;
        trailerBtn.addEventListener('click', function () {
          if (self.detailsData && self.detailsData.videos && self.detailsData.videos.results) {
            var trailer = self.detailsData.videos.results.find(function (v) {
              return v.site === 'YouTube' && (v.type === 'Trailer' || v.type === 'Teaser');
            });
