          var episode = parseInt(epCard.getAttribute('data-episode') || '1', 10);
          var epTitle = epCard.getAttribute('data-title') || '';
          var item = self.item || self.detailsData || {};

          global.CinejoyApp.switchView('player', {
            tmdbId: item.id || item.tmdbId,
            type: 'tv',
            season: season,
            episode: episode,
            title: item.title || item.name || '',
            episodeTitle: epTitle
